                      <label class="w-full h-full flex items-center justify-center cursor-pointer">
                        <input accept="image/*" class="hidden add-pet-photo-input" data-photo-slot="${e}" type="file" />
                        ${t?`<img src="${t}" alt="صورة ${e+1}" class="w-full h-full object-cover" />`:`<span class="text-4xl font-black ${n?`text-[#e67e22]`:`text-[#998b7c]`} group-hover:scale-110 transition-transform">+</span>`}
                      </label>
